+function normalizeSiteBasePath(
+	siteUrl: string | undefined,
+): string | undefined {
+	if (siteUrl === undefined || siteUrl.length === 0) {
+		return undefined;
+	}
+
+	try {
+		const pathname = new URL(siteUrl).pathname.replace(/\/$/u, "");
+		return pathname.length === 0 ? undefined : pathname;
+	} catch {
+		return undefined;
+	}
+}
+
+function resolveExportedPageUrl(
+	url: string,
+	exportedPageUrlMap: ReadonlyMap<string, string>,
+	siteBasePath?: string,
+): string | undefined {
+	const mappedUrl = exportedPageUrlMap.get(url);
+	if (mappedUrl !== undefined) {
+		return mappedUrl;
+	}
+
+	try {
+		const pathname = new URL(url).pathname;
+		const normalizedPathname =
+			siteBasePath !== undefined && pathname.startsWith(`${siteBasePath}/`)
+				? pathname.slice(siteBasePath.length)
+				: pathname;
+		return (
+			exportedPageUrlMap.get(pathname) ??
+			exportedPageUrlMap.get(normalizedPathname)
+		);
+	} catch {
+		return undefined;
+	}
+}
+
+function rewriteExportedPageLinkInlines(
+	inlines: MarkdownInline[],
+	exportedPageUrlMap: ReadonlyMap<string, string>,
+	siteBasePath?: string,
+): MarkdownInline[] {
+	return inlines.map((inline) => {
+		switch (inline.type) {
+			case "emphasis":
+			case "strong":
+				return {
+					...inline,
+					children: rewriteExportedPageLinkInlines(
+						inline.children,
+						exportedPageUrlMap,
+						siteBasePath,
+					),
+				};
+			case "link":
+				return {
+					...inline,
+					url:
+						resolveExportedPageUrl(
+							inline.url,
+							exportedPageUrlMap,
+							siteBasePath,
+						) ?? inline.url,
+					children: rewriteExportedPageLinkInlines(
+						inline.children,
+						exportedPageUrlMap,
+						siteBasePath,
+					),
+				};
+			case "xref":
+				return {
+					...inline,
+					url:
+						resolveExportedPageUrl(
+							inline.url,
+							exportedPageUrlMap,
+							siteBasePath,
+						) ?? inline.url,
+					children: rewriteExportedPageLinkInlines(
+						inline.children,
+						exportedPageUrlMap,
+						siteBasePath,
+					),
+				};
+			case "image":
+				return {
+					...inline,
+					alt: rewriteExportedPageLinkInlines(
+						inline.alt,
+						exportedPageUrlMap,
+						siteBasePath,
+					),
+				};
+			default:
+				return inline;
+		}
+	});
+}
